type ElementName =
  | "dot" | "status" | "refresh" | "tree" | "createTest" | "undo" | "assetSource" | "assetDest"
  | "assetImport" | "assetRefresh" | "scriptUrl" | "scriptClass" | "scriptContent" | "scriptWrite" | "componentName"
  | "componentList" | "componentSchema" | "prefabNode"
  | "prefabUrl" | "prefabProbe" | "prefabCreate" | "prefabOpen" | "prefabSave" | "prefabClose"
  | "prefabParent" | "prefabSemanticKey" | "prefabInstantiate"
  | "method" | "params" | "confirm" | "run" | "result" | "audit" | "copyAudit"
  | "codexStatus" | "installCodex" | "openCompanion" | "refreshCodex" | "promptList"
  | "capabilityProfile" | "currentCapability" | "capabilityPending" | "applyCapability" | "copyDiagnostic" | "statusDetails" | "statusToggle" | "toolCatalog";

type PanelThis = {
  $: Record<ElementName, HTMLElement>;
  state?: PanelState;
  timer: ReturnType<typeof setInterval> | undefined;
  busy: boolean;
  refreshing?: boolean;
  codexMcpName?: string;
  integration?: CodexIntegrationState;
  statusCollapsed: boolean;
  pendingCapabilityProfile?: CapabilityProfile;
};

interface CodexIntegrationState {
  name: string;
  available: boolean;
  installed: boolean;
  current: boolean;
  command: string;
  message: string;
  companion: "connected" | "unavailable";
  projectId?: string;
}

function input(panel: PanelThis, name: ElementName): HTMLInputElement { return panel.$[name] as HTMLInputElement; }
function textarea(panel: PanelThis, name: ElementName): HTMLTextAreaElement { return panel.$[name] as HTMLTextAreaElement; }

async function call(method: string, params?: JsonValue): Promise<JsonValue> {
  if (!ALLOWED_METHODS.has(method)) throw new Error(`面板不允许调用工具: ${method}`);
  return Editor.Message.request("creator-ai-bridge", "panel-call", method, params) as Promise<JsonValue>;
}

function renderTree(nodes: SceneNode[], depth = 0): string {
  return nodes.map((node) => {
    const label = `<b>${escapeHtml(node.name)}</b><small>${escapeHtml(node.semanticKey ?? node.key)}</small><span class="components">${node.components.map((item) => escapeHtml(item.type)).join(", ")}</span>`;
    return node.children.length > 0
      ? `<details class="node" style="--depth:${depth}" open><summary>${label}</summary>${renderTree(node.children, depth + 1)}</details>`
      : `<div class="node" style="--depth:${depth}">${label}</div>`;
  }).join("");
}

function escapeHtml(value: string): string {
  return redactText(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
}

function redactText(value: string): string {
  return value
    .replace(/\bBearer\s+[^\s,}"']+/gi, "Bearer [REDACTED]")
    .replace(/((?:token|authorization|secret)\s*[:=]\s*)[^\s,}"']+/gi, "$1[REDACTED]");
}

function sanitizeJson(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sanitizeJson);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [
      key,
      /token|authorization|secret/i.test(key) ? "[REDACTED]" : sanitizeJson(item),
    ]));
  }
  return typeof value === "string" ? redactText(value) : value;
}

function safeStringify(value: unknown): string {
  return JSON.stringify(sanitizeJson(value), null, 2);
}

function errorText(error: unknown): string {
  return redactText(error instanceof Error ? error.message : String(error));
}

async function copyText(panel: PanelThis, value: string, label: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(redactText(value));
    panel.$.result.textContent = `${label}已复制`;
  } catch (error) {
    panel.$.result.textContent = `复制失败: ${errorText(error)}`;
  }
}

function renderCodexPrompts(panel: PanelThis): void {
  const prompts = CODEX_PROMPTS.map((prompt) => ({
    ...prompt,
    text: prompt.text.replace("cocos-creator MCP", `${panel.codexMcpName ?? "当前工程对应的 Creator"} MCP`),
  }));
  panel.$.promptList.innerHTML = prompts.map((prompt, index) => `<article class="prompt-card"><header><b>${escapeHtml(prompt.title)}</b><button data-copy-prompt="${index}">复制</button></header><p>${escapeHtml(prompt.text)}</p></article>`).join("");
  panel.$.promptList.querySelectorAll<HTMLButtonElement>("button[data-copy-prompt]").forEach((button) => button.addEventListener("click", () => {
    const prompt = prompts[Number(button.dataset.copyPrompt)];
    if (prompt) void copyText(panel, prompt.text, `“${prompt.title}”提示词`);
  }));
}

function renderToolCatalog(panel: PanelThis): void {
  const groups = new Map<string, typeof MCP_TOOL_CATALOG[number][]>();
  for (const tool of MCP_TOOL_CATALOG) groups.set(tool[0], [...(groups.get(tool[0]) ?? []), tool]);
  panel.$.toolCatalog.innerHTML = [...groups].map(([group, tools]) => `
    <details class="tool-group" open><summary>${escapeHtml(group)}（${tools.length}）</summary>
      ${tools.map(([, name, access, description]) => `<div class="tool-row"><code>${escapeHtml(name)}</code><span class="tool-access">${escapeHtml(access)}</span><span class="tool-description">${escapeHtml(description)}</span></div>`).join("")}
    </details>`).join("");
}

async function refreshCodexIntegration(panel: PanelThis): Promise<void> {
  try {
    const state = await Editor.Message.request("creator-ai-bridge", "codex-integration-status") as CodexIntegrationState;
    panel.integration = state;
    panel.codexMcpName = state.name;
    renderCodexPrompts(panel);
    panel.$.codexStatus.innerHTML = `
      <b>Companion</b> <span class="${state.companion === "connected" ? "ok" : "bad"}">${state.companion === "connected" ? "已连接" : "未连接"}</span><br>
      <b>Codex MCP</b> ${escapeHtml(state.name)}<br>
      ${state.projectId ? `<b>工程 ID</b> ${escapeHtml(state.projectId)}<br>` : ""}
      <span class="${state.current ? "ok" : state.available ? "" : "bad"}">${escapeHtml(state.message)}</span>`;
    const installButton = panel.$.installCodex as HTMLButtonElement;
    installButton.textContent = state.current ? "修复接入" : state.installed ? "迁移到 Companion" : "启动并接入";
    installButton.classList.toggle("installed", state.current);
    installButton.disabled = !state.available || panel.busy;
    render(panel);
  } catch (error) {
    panel.$.codexStatus.innerHTML = `<span class="bad">${escapeHtml(errorText(error))}</span>`;
  }
}

async function installCodex(panel: PanelThis): Promise<void> {
  if (panel.busy) return;
  setBusy(panel, true);
  panel.$.codexStatus.textContent = "Companion 正在注册工程、验证 Bridge 并接入 Codex...";
  try {
    const state = await Editor.Message.request("creator-ai-bridge", "codex-integration-install") as CodexIntegrationState;
    panel.$.result.textContent = state.message;
  } catch (error) {
    panel.$.result.textContent = `接入失败: ${errorText(error)}`;
  } finally {
    setBusy(panel, false);
    await refreshCodexIntegration(panel);
  }
}

function setBusy(panel: PanelThis, busy: boolean): void {
  panel.busy = busy;
  const root = panel.$.result.getRootNode() as ParentNode;
  root.querySelectorAll<HTMLButtonElement>("button[data-exec]").forEach((button) => { button.disabled = busy; });
}

function setStatusCollapsed(panel: PanelThis, collapsed: boolean): void {
  panel.statusCollapsed = collapsed;
  panel.$.statusDetails.hidden = collapsed;
  panel.$.statusToggle.textContent = collapsed ? "展开状态" : "收起状态";
  panel.$.statusToggle.setAttribute("aria-expanded", String(!collapsed));
  localStorage.setItem("creator-ai-bridge.status-collapsed", String(collapsed));
}

function render(panel: PanelThis): void {
  const state = panel.state;
  const integration = panel.integration;
  panel.$.dot.classList.toggle("on", Boolean(state?.connected));
  panel.$.status.innerHTML = state ? `
    <b>Bridge</b><span>${state.connected ? "已连接" : "未连接"}</span>
    <b>Creator</b><span>${escapeHtml(state.project.creatorVersion)}</span>
    <b>协议</b><span>${escapeHtml(state.project.protocolVersion)}</span>
    <b>工程</b><span title="${escapeHtml(state.project.projectPath)}">${escapeHtml(state.project.projectPath)}</span>
    <b>会话</b><span>${escapeHtml(state.project.sessionId)}</span>
    <b>Companion</b><span class="${integration?.companion === "connected" ? "ok" : "bad"}">${integration?.companion === "connected" ? "已连接" : "未连接"}</span>
    <b>Codex MCP</b><span>${escapeHtml(integration?.name ?? "待检测")}</span>
    <b>文档</b><span>${escapeHtml(state.document?.sceneUrl ?? "未打开")}</span>
    <b>Revision</b><span>${escapeHtml(state.document?.revision ?? "-")}</span>` : "未连接";
  panel.$.tree.innerHTML = state?.document ? renderTree(state.document.roots) : "无场景数据";
  if (state) {
    const capability = capabilitySelectionState(state.capabilityProfile, panel.pendingCapabilityProfile);
    panel.pendingCapabilityProfile = capability.selected;
    (panel.$.capabilityProfile as HTMLSelectElement).value = capability.selected;
    panel.$.currentCapability.textContent = capability.effectiveLabel;
    panel.$.capabilityPending.textContent = capability.pending ? `待应用：${capability.selectedLabel}` : "已应用";
    panel.$.capabilityPending.classList.toggle("bad", capability.pending);
    panel.$.capabilityPending.classList.toggle("ok", !capability.pending);
  }
  panel.$.audit.innerHTML = (state?.audit ?? []).slice(-100).map((event: AuditEvent) => `<div class="audit-row"><span class="${event.ok ? "ok" : "bad"}">${event.ok ? "OK" : "FAIL"}</span> ${escapeHtml(event.method)} · ${event.durationMs}ms<br><small>${escapeHtml(event.startedAt)} · ${escapeHtml(event.errorCode ?? "-")} · ${escapeHtml(event.summary)}</small></div>`).join("");
}

async function applyCapabilityProfile(panel: PanelThis): Promise<void> {
  if (panel.busy) return;
  const profile = (panel.$.capabilityProfile as HTMLSelectElement).value as CapabilityProfile;
  if (profile === "full-control" && !window.confirm("完全控制将允许带精确确认串的节点和资源删除。确认启用？")) return;
  setBusy(panel, true);
  try {
    const applied = await Editor.Message.request("creator-ai-bridge", "set-capability-profile", profile) as CapabilityProfile;
    const state = await Editor.Message.request("creator-ai-bridge", "panel-state") as PanelState;
    panel.state = state;
    panel.pendingCapabilityProfile = profile;
    render(panel);
    if (applied !== profile || state.capabilityProfile !== profile) {
      throw new Error(`Creator 权限状态冲突：请求 ${capabilityProfileLabel(profile)}，返回 ${capabilityProfileLabel(applied)}，当前生效 ${capabilityProfileLabel(state.capabilityProfile)}`);
    }
    panel.$.result.textContent = `Creator 权限已切换为 ${capabilityProfileLabel(profile)}`;
  } catch (error) {
    panel.$.result.textContent = errorText(error);
  } finally {
    setBusy(panel, false);
  }
}

async function copyDiagnostic(panel: PanelThis): Promise<void> {
  try {
    const diagnostic = await Editor.Message.request("creator-ai-bridge", "diagnostic-snapshot") as DiagnosticSnapshot;
    await copyText(panel, safeStringify(diagnostic), "诊断信息");
  } catch (error) {
    panel.$.result.textContent = `诊断生成失败: ${errorText(error)}`;
  }
}

async function refresh(panel: PanelThis): Promise<void> {
  if (panel.refreshing) return;
  panel.refreshing = true;
  try {
    panel.state = await Editor.Message.request("creator-ai-bridge", "panel-state") as PanelState;
    render(panel);
  } catch (error) {
    panel.$.result.textContent = errorText(error);
  } finally {
    panel.refreshing = false;
  }
}

async function run(panel: PanelThis, method: string, params?: JsonValue, confirmWrite = false): Promise<JsonValue | undefined> {
  if (panel.busy) return;
  if (confirmWrite && !window.confirm(`确认执行写操作 ${method}？`)) return;
  setBusy(panel, true);
  panel.$.result.textContent = `执行 ${method}...`;
  try {
    const result = await call(method, params);
    panel.$.result.textContent = safeStringify(result);
    await refresh(panel);
    return result;
  } catch (error) {
    panel.$.result.textContent = errorText(error);
  } finally {
    setBusy(panel, false);
  }
}

async function writeAndCompile(panel: PanelThis): Promise<void> {
  if (panel.busy || !window.confirm("确认写入 TypeScript 脚本并等待 Creator 编译？")) return;
  setBusy(panel, true);
  const url = input(panel, "scriptUrl").value;
  panel.$.result.textContent = `检查 ${url}...`;
  try {
    const current = await call("asset.getInfo", { value: url }) as { hash?: string } | null;
    const written = await call("script.write", { url, content: textarea(panel, "scriptContent").value, expectedHash: current?.hash ?? null });
    const compiled = await call("script.waitCompile", { url, className: input(panel, "scriptClass").value, timeoutMs: 30000 });
    panel.$.result.textContent = safeStringify({ written, compiled });
    await refresh(panel);
  } catch (error) {
    panel.$.result.textContent = errorText(error);
  } finally {
    setBusy(panel, false);
  }
}

module.exports = Editor.Panel.define({
  template,
  style,
  $: {
    dot: "#dot", status: "#status", refresh: "#refresh", tree: "#tree", createTest: "#createTest", undo: "#undo",
    assetSource: "#assetSource", assetDest: "#assetDest", assetImport: "#assetImport", scriptUrl: "#scriptUrl",
    assetRefresh: "#assetRefresh", scriptClass: "#scriptClass", scriptContent: "#scriptContent", scriptWrite: "#scriptWrite",
    componentName: "#componentName", componentList: "#componentList", componentSchema: "#componentSchema", prefabNode: "#prefabNode",
    prefabUrl: "#prefabUrl", prefabProbe: "#prefabProbe", prefabCreate: "#prefabCreate", prefabOpen: "#prefabOpen",
    prefabSave: "#prefabSave", prefabClose: "#prefabClose", prefabParent: "#prefabParent",
    prefabSemanticKey: "#prefabSemanticKey", prefabInstantiate: "#prefabInstantiate",
    method: "#method", params: "#params", confirm: "#confirm",
    run: "#run", result: "#result", audit: "#audit", copyAudit: "#copyAudit",
    codexStatus: "#codexStatus", installCodex: "#installCodex", openCompanion: "#openCompanion", refreshCodex: "#refreshCodex",
    promptList: "#promptList",
    capabilityProfile: "#capabilityProfile", currentCapability: "#currentCapability", capabilityPending: "#capabilityPending",
    applyCapability: "#applyCapability", copyDiagnostic: "#copyDiagnostic",
    statusDetails: "#statusDetails", statusToggle: "#statusToggle", toolCatalog: "#toolCatalog",
  },
  listeners: {
    show(this: PanelThis) { void refresh(this); this.timer ??= setInterval(() => void refresh(this), 2000); },
    hide(this: PanelThis) { if (this.timer) clearInterval(this.timer); this.timer = undefined; },
  },
  ready(this: PanelThis) {
    this.statusCollapsed = localStorage.getItem("creator-ai-bridge.status-collapsed") === "true";
    setStatusCollapsed(this, this.statusCollapsed);
    setBusy(this, false);
    (this.$.method as HTMLSelectElement).innerHTML = TOOL_METHODS.map((method) => `<option>${method}</option>`).join("");
    textarea(this, "scriptContent").value = `import { _decorator, Button, Component } from 'cc';\nconst { ccclass, property } = _decorator;\n@ccclass('StartButton')\nexport class StartButton extends Component {\n  @property(Button) button: Button | null = null;\n}`;
    this.$.refresh.addEventListener("click", () => void refresh(this));
    this.$.statusToggle.addEventListener("click", () => setStatusCollapsed(this, !this.statusCollapsed));
    this.$.capabilityProfile.addEventListener("change", () => {
      this.pendingCapabilityProfile = (this.$.capabilityProfile as HTMLSelectElement).value as CapabilityProfile;
      render(this);
    });
    this.$.applyCapability.addEventListener("click", () => void applyCapabilityProfile(this));
    this.$.copyDiagnostic.addEventListener("click", () => void copyDiagnostic(this));
    const panelRoot = this.$.result.getRootNode() as ParentNode;
    panelRoot.querySelectorAll("nav button").forEach((button) => button.addEventListener("click", () => {
      panelRoot.querySelectorAll("nav button").forEach((item) => item.classList.toggle("active", item === button));
      panelRoot.querySelectorAll("[data-page]").forEach((page) => ((page as HTMLElement).hidden = page.getAttribute("data-page") !== button.getAttribute("data-tab")));
      if (button.getAttribute("data-tab") === "help") void refreshCodexIntegration(this);
    }));
    renderCodexPrompts(this);
    renderToolCatalog(this);
    this.$.installCodex.addEventListener("click", () => void installCodex(this));
    this.$.openCompanion.addEventListener("click", () => void Editor.Message.request("creator-ai-bridge", "open-companion").catch((error) => { this.$.result.textContent = `打开 Companion 失败: ${errorText(error)}`; }));
    this.$.refreshCodex.addEventListener("click", () => void refreshCodexIntegration(this));
    this.$.createTest.addEventListener("click", () => {
      const revision = this.state?.document?.revision;
      if (revision) void run(this, "scene.applyPatch", { expectedRevision: revision, verify: true, save: true, operations: [{ op: "upsertNode", key: "CreatorAiPanelTest", name: "CreatorAiPanelTest" }] }, true);
    });
    this.$.undo.addEventListener("click", () => void run(this, "scene.undoLastWrite", undefined, true));
    this.$.assetImport.addEventListener("click", () => void run(this, "asset.import", { sourcePath: input(this, "assetSource").value, destinationUrl: input(this, "assetDest").value }, true));
    this.$.assetRefresh.addEventListener("click", () => void run(this, "asset.refresh", { url: input(this, "assetDest").value }, true));
    this.$.scriptWrite.addEventListener("click", () => void writeAndCompile(this));
    this.$.componentList.addEventListener("click", () => void run(this, "component.listAvailable"));
    this.$.componentSchema.addEventListener("click", () => void run(this, "component.getSchema", { name: input(this, "componentName").value }));
    this.$.prefabProbe.addEventListener("click", () => void run(this, "prefab.probe"));
    this.$.prefabCreate.addEventListener("click", () => void run(this, "prefab.create", { sourceNodeKey: input(this, "prefabNode").value, url: input(this, "prefabUrl").value }, true));
    this.$.prefabOpen.addEventListener("click", () => void run(this, "prefab.open", { url: input(this, "prefabUrl").value }, true));
    this.$.prefabSave.addEventListener("click", () => void run(this, "prefab.save", undefined, true));
    this.$.prefabClose.addEventListener("click", () => void run(this, "prefab.close", undefined, true));
    this.$.prefabInstantiate.addEventListener("click", () => {
      const revision = this.state?.document?.revision;
      if (!revision) { this.$.result.textContent = "当前没有可用的场景 revision"; return; }
      const parentKey = input(this, "prefabParent").value.trim();
      const params: Record<string, JsonValue> = {
        url: input(this, "prefabUrl").value,
        semanticKey: input(this, "prefabSemanticKey").value,
        expectedRevision: revision,
      };
      if (parentKey) params.parentKey = parentKey;
      void run(this, "prefab.instantiate", params, true);
    });
    this.$.run.addEventListener("click", () => {
      const method = (this.$.method as HTMLSelectElement).value;
      if (!READ_METHODS.has(method) && !(input(this, "confirm") as HTMLInputElement).checked) {
        this.$.result.textContent = "写操作必须勾选确认";
        return;
      }
      try {
        const params = JSON.parse(textarea(this, "params").value) as unknown;
        if (params === null || Array.isArray(params) || typeof params !== "object") throw new Error("参数必须是 JSON 对象");
        void run(this, method, params as JsonValue).then((result) => {
          if (result !== undefined && !READ_METHODS.has(method)) input(this, "confirm").checked = false;
        });
      } catch (error) { this.$.result.textContent = `JSON 无效: ${errorText(error)}`; }
    });
    this.$.copyAudit.addEventListener("click", () => void navigator.clipboard.writeText(safeStringify((this.state?.audit ?? []).slice(-100))));
    void refreshCodexIntegration(this);
    void refresh(this);
  },
  beforeClose() {},
  close(this: PanelThis) { if (this.timer) clearInterval(this.timer); this.timer = undefined; },
});
