import { mkdir, readFile, writeFile } from "node:fs/promises";
import type { CapabilityProfile } from "../../mcp/src/protocol.js";

export const CAPABILITY_PROFILES = new Set<CapabilityProfile>(["read-only", "authoring", "full-control"]);

const CAPABILITY_PROFILE_LABELS: Record<CapabilityProfile, string> = {
  "read-only": "只读",
  authoring: "创作",
  "full-control": "完全控制",
};

export function capabilityProfileLabel(profile: CapabilityProfile): string {
  return CAPABILITY_PROFILE_LABELS[profile];
}

export interface CapabilityProfileIo {
  mkdir(path: string): Promise<void>;
  read(path: string): Promise<string>;
  write(path: string, content: string): Promise<void>;
}

const nodeIo: CapabilityProfileIo = {
  async mkdir(path) { await mkdir(path, { recursive: true }); },
  read(path) { return readFile(path, "utf8"); },
  async write(path, content) { await writeFile(path, content); },
};

export async function readStoredCapabilityProfile(
  path: string,
  io: CapabilityProfileIo = nodeIo,
): Promise<CapabilityProfile> {
  const value = (JSON.parse(await io.read(path)) as { capabilityProfile?: unknown }).capabilityProfile;
  if (typeof value !== "string" || !CAPABILITY_PROFILES.has(value as CapabilityProfile)) {
    throw new Error("Stored capability profile is invalid");
  }
  return value as CapabilityProfile;
}

export async function persistAndApplyCapabilityProfile(
  settingsDirectory: string,
  path: string,
  profile: CapabilityProfile,
  service: { getCapabilityProfile(): CapabilityProfile; setCapabilityProfile(profile: CapabilityProfile): void },
  io: CapabilityProfileIo = nodeIo,
): Promise<CapabilityProfile> {
  const previous = service.getCapabilityProfile();
  await io.mkdir(settingsDirectory);
  await io.write(path, JSON.stringify({ capabilityProfile: profile }, null, 2));
  const stored = await readStoredCapabilityProfile(path, io);
  if (stored !== profile) throw new Error(`Capability profile persistence mismatch: expected ${profile}, received ${stored}`);

  try {
    service.setCapabilityProfile(profile);
    const effective = service.getCapabilityProfile();
    if (effective !== profile) throw new Error(`Capability profile state conflict: expected ${profile}, received ${effective}`);
    return effective;
  } catch (error) {
    service.setCapabilityProfile(previous);
    try {
      await io.write(path, JSON.stringify({ capabilityProfile: previous }, null, 2));
      const restored = await readStoredCapabilityProfile(path, io);
      if (restored !== previous) throw new Error(`expected ${previous}, received ${restored}`);
    } catch (rollbackError) {
      throw new Error(`Capability profile update failed and persistence rollback failed: ${error instanceof Error ? error.message : String(error)}; ${rollbackError instanceof Error ? rollbackError.message : String(rollbackError)}`);
    }
    throw error;
  }
}

export function capabilitySelectionState(effective: CapabilityProfile, selected?: CapabilityProfile) {
  const value = selected ?? effective;
  return {
    selected: value,
    selectedLabel: capabilityProfileLabel(value),
    effectiveLabel: capabilityProfileLabel(effective),
    pending: value !== effective,
  };
}
